              {tagsOf(lb.i).join(' · ')}{!compact && <span style={{ marginLeft: 16, opacity: 0.7, textTransform: 'none', letterSpacing: '0.02em' }}>Double-click to zoom</span>}
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

