                <div style={{ fontSize: compact ? 11 : 12, letterSpacing: '0.16em', textTransform: 'uppercase', animation: reduced ? 'none' : `${p}-rise 900ms ${easeOut} ${overlays.length ? 200 : Math.round(dur * 0.62)}ms both` }}>
