    if (ro) ro.observe(el);
    window.addEventListener('resize', measure);
    let io = null;
    if (!reduced && typeof IntersectionObserver !== 'undefined') {
      io = new IntersectionObserver((es) => { if (es.some((e) => e.isIntersecting)) { setShown(true); io.disconnect(); } }, { threshold: 0.15 });
