                <div ref={(el) => { segRefs.current[i] = el; }} style={{ width: '100%', height: '100%', backgroundColor: ink, transformOrigin: '0 50%', transform: i === 0 ? 'scaleX(1)' : 'scaleX(0)' }} />
              </div>
