        @keyframes ${p}-fade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
        @keyframes ${p}-in { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
