                      <span style={{ fontSize: 11, letterSpacing: '0.1em', textTransform: 'uppercase', color: muted, flexShrink: 0 }}>{s.meta}</span>
                    </button>
                    {on && <div style={{ paddingTop: 8 }}>{description}</div>}
                  </div>
                </div>
              );
            })}
          </div>
        </>
      )}
    </section>
  );
}

